<?php require '_auth.php';$adminTitle='Dashboard';$products=$pdo->query("SELECT COUNT(*) FROM products")->fetchColumn();$orders=$pdo->query("SELECT COUNT(*) FROM orders")->fetchColumn();$users=$pdo->query("SELECT COUNT(*) FROM users")->fetchColumn();$revenue=$pdo->query("SELECT COALESCE(SUM(total),0) FROM orders WHERE status<>'Cancelled'")->fetchColumn();$recent=$pdo->query("SELECT * FROM orders ORDER BY id DESC LIMIT 6")->fetchAll();include '_header.php';?><section class="metric-grid"><div class="metric"><span>Products</span><strong><?=$products?></strong></div><div class="metric"><span>Orders</span><strong><?=$orders?></strong></div><div class="metric"><span>Customers</span><strong><?=$users?></strong></div><div class="metric"><span>Total revenue</span><strong>LKR <?=number_format($revenue,0)?></strong></div></section><section class="panel"><div class="panel-head"><h2>Recent orders</h2><a class="btn" href="orders.php">Manage orders</a></div><table class="table"><tr><th>Order</th><th>Customer</th><th>Total</th><th>Status</th><th>Date</th></tr><?php foreach($recent as $o):?><tr><td>#<?=$o['id']?></td><td><?=e($o['customer_name'])?></td><td>LKR <?=number_format($o['total'],2)?></td><td><span class="status"><?=e($o['status'])?></span></td><td><?=e($o['created_at'])?></td></tr><?php endforeach;?></table></section><?php include '_footer.php';?>
